"""Coverage probe: do random cases actually exercise changing supports/ties?"""
import json, random, sys
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tmp')
import diff_test
from crosscheck.common_utils import Topology, Plan, select_band
from crosscheck.dtp import RepairEngine, band_from_list

changed = 0
ties = 0
cases = 0
clamped = 0
empty_pool = 0
for case in range(150):
    rng = random.Random(9000+case)
    stream = diff_test.make_stream(rng, nodes=rng.randint(3,7), ext=rng.randint(2,3), events=8)
    topo = Topology(stream["topology"])
    ev = stream["events"]
    st = stream["settings"]
    counters, demands, plan = {}, {}, None
    engine = RepairEngine(topo)
    trials, eps, seed = st["trials"], st["epsilon"], st["seed"]
    for e in ev:
        if e["op"] == "patch":
            if rng.random() < 0.5:
                continue
            for k, c in e["counters"].items():
                if c is None: counters.pop(k, None)
                elif c.get("perturbed") is None: counters.pop(k, None)
                else: counters[k] = c["perturbed"]
            for d in e["demands"]: demands[(d[0], d[1])] = d[2]
        elif e["op"] == "routes":
            plan = None if e["paths"] is None else Plan(e["paths"], topo)
        elif e["op"] == "repair":
            # literal from-scratch supports at each prefix
            loads = [None]*len(topo.flows)
            out_m={}; in_m={}
            for (s,d),v in demands.items():
                out_m[s]=out_m.get(s,0)+v; in_m[d]=in_m.get(d,0)+v
            for f in topo.flows:
                if f.src==-1: loads[f.index]=out_m.get(f.dst,0)
                elif f.dst==-1: loads[f.index]=in_m.get(f.src,0)
            if plan is not None:
                for fi,tot in plan.internal_loads(demands).items(): loads[fi]=tot//1000
            pools, base = engine.build_pools(counters, loads, plan is not None, trials)
            samples = engine.sample_values(pools, seed, trials)
            for p in pools:
                if not p: empty_pool += 1
            frozen = {}
            remaining = list(range(len(topo.flows)))
            prev = {}
            local_changed = False
            while remaining:
                scores = {}
                for fi in remaining:
                    ev_items = dict(base[fi])
                    for rid, pos in topo.flow_slots[fi]:
                        cap = topo.flows[fi].cap
                        sign = topo.router_signs[rid][pos]
                        rems = []
                        vals = {}
                        for t in range(trials):
                            for pos2, other in enumerate(topo.router_flows[rid]):
                                if other in frozen:
                                    vals[other] = frozen[other]
                                else:
                                    vals[other] = samples[rid][pos2][t]
                            s = vals[fi] if fi not in frozen else frozen[fi]
                            other_in = sum(v for g, v in vals.items()
                                            if g != fi and topo.flows[g].dst == rid)
                            other_out = sum(v for g, v in vals.items()
                                            if g != fi and topo.flows[g].src == rid)
                            rem = (other_in - other_out) if sign < 0 else (other_out - other_in)
                            rem = max(0, min(cap, rem))
                            if rem != (other_out - other_in if sign > 0 else other_in - other_out):
                                pass
                            rems.append(rem)
                        rep, mass = band_from_list(rems, eps)
                        ev_items[rep] = ev_items.get(rep, 0) + mass
                    scores[fi] = select_band(ev_items, eps)
                best = min(remaining, key=lambda f: (-scores[f][1], topo.flows[f].pair))
                tie_count = sum(1 for f in remaining if scores[f][1] == scores[best][1])
                if tie_count > 1: ties += 1
                for f in remaining:
                    if f in prev and prev[f] != scores[f][1]:
                        local_changed = True
                prev = {f: scores[f][1] for f in remaining}
                frozen[best] = scores[best][0]
                remaining.remove(best)
            if local_changed: changed += 1
            cases += 1
print("repairs analysed", cases, "with support changes across prefixes:", changed,
      "tie events:", ties, "empty pools:", empty_pool)
PYEOF
